from threetears.evals import Eval

from stockroom import Line, order_quantity, reorder_point

FIELDS = ("sku", "name", "sold", "window_days", "lead_days", "safety_days", "on_hand", "on_order", "pack")


def review(case):
    """The line's reorder point and today's order, as the sheet works them out."""
    line = Line(**{field: case[field] for field in FIELDS})
    return {"point": reorder_point(line), "order": order_quantity(line)}


def matches_sheet(case, out):
    """The reorder point and the order are the buyer's spreadsheet's."""
    return (out["point"], out["order"]) == (case["sheet_reorder_point"], case["sheet_order"])

review_sheet = Eval("data/stock_review.jsonl", runner=review, grader=[matches_sheet], k=1)
